char *read_file_from_dir(const char *filename, const char *dir_path) {
    char full_path[1024];
    snprintf(full_path, sizeof(full_path), "%s/%s", dir_path, filename);

    // Check if the path is safe (prevent directory traversal)
    if (strchr(full_path, '/')) {
        // If the full path contains a slash, it's potentially unsafe
        return strdup("");
    }

    int fd = open(full_path, O_RDONLY);
    if (fd == -1) {
        return strdup("");
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        close(fd);
        return strdup("");
    }

    char *content = (char *)malloc(st.st_size + 1);
    if (!content) {
        close(fd);
        return strdup("");
    }

    ssize_t bytes_read = read(fd, content, st.st_size);
    if (bytes_read == -1 || (size_t)bytes_read != st.st_size) {
        free(content);
        close(fd);
        return strdup("");
    }

    content[st.st_size] = '\0';
    close(fd);
    return content;
}
